fn tri(n: usize, m: usize, k: i32) -> Vec<Vec<f64>> {
    let mut matrix = Vec::with_capacity(n);
    for i in 0..n {
        let mut row = Vec::with_capacity(m);
        // i and j are usize, k is i32, so convert i to i32 for calculation
        let limit = (i as i32) + k;
        for j in 0..m {
            // j as i32 for comparison
            if (j as i32) <= limit {
                row.push(1.0);
            } else {
                row.push(0.0);
            }
        }
        matrix.push(row);
    }
    matrix
}